={
  "task": "normalize_position_name_for_commercial_offer",
  "description": "Отформатировать название позиции для коммерческого предложения (КП) на основе входных данных и строгих правил.",
  "language": "ru",
  "input_schema": {
    "Наименование": "string — исходное наименование позиции",
    "Ед.Измерения": "string — единица измерения (например, 'шт')",
