    },
    {
      "input": {
        "Наименование": "Ареометры АУ 1000-1050 (урометр)",
        "Кол-во в упак.": "1 шт",
        "Ед.Измерения": "шт",
        "Рег.номер": null
      },
      "output": "Ареометр АУ 1000-1050 (урометр) уп. 1 шт"
    },
    {
      "input": {
        "Наименование": "Воронки делительные грушевидные с делениями ВД-3-125",
        "Кол-во в упак.": "2/48 шт",
        "Ед.Измерения": "шт",
        "Рег.номер": null
      },
      "output": "Воронка делительная грушевидная с делениями ВД-3-125 уп. 2 шт"
    },
    {
      "input": {
        "Наименование": "Стекло для микропрепаратов (покровное) 18х18 мм",
        "Кол-во в упак.": "1000/50000 шт",
        "Ед.Измерения": "шт",
        "Рег.номер": "РУ № РЗН 2015/2981"
      },
      "output": "Стекло для микропрепаратов (покровное) 18х18 мм уп. 1000 шт, РУ № РЗН 2015/2981"
    },
    {
      "input": {
        "Наименование": "Бутылка для крови, трансфузионных и инфузионных препаратов ll-50-2-МТО",
        "Кол-во в упак.": null,
        "Ед.Измерения": "шт",
        "Рег.номер": "РУ № ФСР 2011/11410"
      },
      "output": "Бутылка для крови, трансфузионных и инфузионных препаратов ll-50-2-МТО, РУ № ФСР 2011/11410"
    }
  ],
  "constraints": [
    "Строго соблюдать порядок элементов в итоговом наименовании.",
    "Не добавлять элементы, которых нет во входных данных.",
    "Не изменять артикулы, модели, каталожные номера (например, 'll-50-2-МТО', 'АУ 1000-1050', 'ВД-3-125').",
    "Не изменять размеры и единицы измерения внутри наименования (например, '18х18 мм', '50 мл').",
    "Категория товара (первое существительное) всегда ставится в единственное число и в начало.",
    "Страна, если указана в наименовании, переносится в конец после упаковки.",
    "Регистрационный номер всегда в самом конце.",
    "Если поле 'Кол-во в упак.' пустое или отсутствует — блок 'уп. N <ед.изм>' не добавляется.",
    "Если поле 'Рег.номер' пустое или отсутствует — блок ', РУ № ...' не добавляется."
  ]
}

