/* =========================================================================
 *  n8n Code node — формирование строки коммерческого предложения (JSON)
 *  Режим запуска: Run Once for All Items (используем .first() во всех нодах)
 *
 *  ИСТОЧНИКИ ДАННЫХ (ноды):
 *    $input.first().json.output                          — наименование
 *    $('Loop Over Items')                                — кол-во, ед.изм. КП
 *    $('Запрос всех данных о позиции')                   — данные товара
 *    $('Получить курсы валют')                           — курсы USD/EUR/CNY
 *    $('Получить данныне по Ед.измерения')               — правила пересчёта ед.изм.
 *    $('Получить базовую наценку')                       — % наценки по умолчанию
 * ========================================================================= */

// Надбавка за конвертацию валюты (ЦБ + 5%)
const CONVERSION_FEE = 0.05;

// Порог, по которому определяем: значение наценки задано как % (>5) или как множитель (<=5)
const MARKUP_PERCENT_THRESHOLD = 5;

/**
 * Список "мелких" единиц измерения.
 * Для них цена за единицу округляется до 4 знаков после запятой,
 * потому что цена за 1 г/мг/мл/мкл обычно меньше 1 рубля
 * и округление до целых рублей сильно завышает итог.
 * Все остальные единицы (кг, л, м, шт. и т.д.) округляются до целых рублей.
 */
const SMALL_UNITS = new Set(['г', 'мг', 'мл', 'мкл']);

/* -------------------------------------------------------------------------
 * 1. ЧТЕНИЕ ВХОДНЫХ ДАННЫХ ИЗ ДРУГИХ НОД
 * ---------------------------------------------------------------------- */

// Текущий элемент (например, строка из цикла или результат LLM-ноды)
const curItem = $input.first().json;

// Элемент из цикла Loop Over Items — там кол-во и ед.изм. запроса
const loopItem = $('Loop Over Items').first().json;

// Данные о товаре из прайса (цена, ставка НДС, единица измерения, валюта и т.д.)
const pos = $('Запрос всех данных о позиции').first().json;

// Справочник курсов валют (массив объектов {код_валюты, значение})
// Ответ может приходить обёрнутым в [{data: [...]}] — разворачиваем.
const unwrap = (v) =>
  Array.isArray(v) && v.length && Array.isArray(v[0]?.data) ? v[0].data : v;

const rates     = unwrap($('Получить курсы валют').first().json.data)             || [];
const unitRules = unwrap($('Получить данныне по Ед.измерения').first().json.data) || [];

/* -------------------------------------------------------------------------
 * 2. ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ПАРСИНГА И ОКРУГЛЕНИЯ
 * ---------------------------------------------------------------------- */

/**
 * Парсинг цены из прайса.
 * Правила формата из ТЗ:
 *   запятая = разделитель разрядов (удаляем),
 *   точка   = десятичный разделитель  (сохраняем).
 *   "2,193.00" → 2193.00
 *   "232.25"   → 232.25
 *   "190.94"   → 190.94
 */
function parsePrice(v) {
  if (v === null || v === undefined) return 0;
  if (typeof v === 'number') return isFinite(v) ? v : 0;
  const s = String(v)
    .trim()
    .replace(/\s|\u00A0/g, '') // пробелы и неразрывные пробелы
    .replace(/,/g, '');        // запятая — разделитель тысяч, убираем
  const n = parseFloat(s);
  return isFinite(n) ? n : 0;
}

/**
 * Парсинг количества.
 * Может прийти как число или строка с запятой в роли десятичного разделителя
 * ("1,5" → 1.5) либо с точкой (".5" → 0.5, "1.5" → 1.5).
 */
function parseQty(v) {
  if (typeof v === 'number') return isFinite(v) ? v : 0;
  if (v === null || v === undefined) return 0;
  let s = String(v).trim().replace(/\s|\u00A0/g, '');
  if (s.includes(',') && !s.includes('.')) s = s.replace(',', '.');
  else s = s.replace(/,/g, '');
  const n = parseFloat(s);
  return isFinite(n) ? n : 0;
}

/**
 * Парсинг ставки НДС.
 * Возвращает число (22, 10, 0). Для "Без НДС" / пусто / "нет" — 0.
 */
function parseVat(v) {
  if (v === null || v === undefined) return 0;
  if (typeof v === 'number') return isFinite(v) ? v : 0;
  const s = String(v).trim().toLowerCase();
  if (!s || s.includes('без') || s.includes('нет')) return 0;
  const n = parseFloat(s.replace('%', '').replace(',', '.'));
  return isFinite(n) ? n : 0;
}

/**
 * Округление до целых рублей по математическому правилу:
 *   0.50 и выше — вверх, менее 0.50 — вниз.
 * Math.round делает именно это для положительных чисел.
 * Добавляем 1e-9, чтобы компенсировать floating-point (например 325.5 → 326).
 */
const roundRub = (x) => Math.round(x + 1e-9);

/** Округление до 2 знаков (копеек). */
const round2 = (x) => Math.round((x + Number.EPSILON) * 100) / 100;

/** Округление до 4 знаков (для мелких единиц измерения: г, мг, мл, мкл). */
const round4 = (x) => Math.round((x + Number.EPSILON) * 10000) / 10000;

/**
 * Нормализация единицы измерения для сопоставления.
 * Приводит: "кг.", "КГ", " Кг " → "кг"
 *            "Шт."             → "шт"
 *            "упак."           → "упак"
 *            "м²"              → "м²"
 */
const normUnit = (v) =>
  String(v ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .replace(/\.+$/, ''); // убираем завершающую точку

/**
 * 🔧 ОКРУГЛЕНИЕ ЦЕНЫ ЗА ЕДИНИЦУ С УЧЁТОМ РАЗМЕРА ЕДИНИЦЫ:
 *   - мелкие единицы (г, мг, мл, мкл) → 4 знака после запятой;
 *   - всё остальное (кг, л, м, шт., упак., пар., см, мм и т.д.)
 *     → до целых рублей по правилу 0.50↑ / 0.49↓.
 */
function roundUnitPrice(price, unit) {
  const u = normUnit(unit);
  if (SMALL_UNITS.has(u)) return round4(price);
  return roundRub(price);
}

/* -------------------------------------------------------------------------
 * 3. КОНВЕРТАЦИЯ ВАЛЮТЫ (СНАЧАЛА ЭТОТ ШАГ, ПОТОМ НАЦЕНКА)
 * ---------------------------------------------------------------------- */

/**
 * Перевод суммы в рубли по курсу ЦБ + 5% за конвертацию.
 * Если валюта RUB (или пустая) — возвращаем как есть.
 */
function toRub(amount, currency, rates) {
  const cur = String(currency ?? 'RUB').trim().toUpperCase();
  if (!cur || cur === 'RUB' || cur === 'РУБ' || cur === '643') return amount;

  const r = rates.find(
    (x) => String(x.код_валюты ?? x.code ?? '').trim().toUpperCase() === cur
  );
  if (!r) return amount; // курс не найден — оставляем как есть

  const rate = parsePrice(r.значение ?? r.value ?? 0);
  if (!rate) return amount;

  return amount * rate * (1 + CONVERSION_FEE);
}

/* -------------------------------------------------------------------------
 * 4. ПЕРЕСЧЁТ ЦЕНЫ ПРИ РАЗЛИЧНЫХ ЕДИНИЦАХ ИЗМЕРЕНИЯ
 * ---------------------------------------------------------------------- */

/**
 * Пересчёт цены из единицы прайса в единицу запроса.
 *
 * Пример: цена 622.20 ₽ за 1 кг, запрос в граммах.
 *   правило: единица_в_прайсе="кг", единица_в_запросе="г",
 *            операция="разделить", коэффициент=1000
 *   → 622.20 / 1000 = 0.6222 ₽ за 1 г
 *
 * Для динамических коэффициентов (упак. ↔ шт.) используем perPack —
 * значение поля "Кол-во в упак." из позиции.
 */
function convertUnit(price, priceUnit, reqUnit, rules, perPack = 0) {
  const pu = normUnit(priceUnit);
  const ru = normUnit(reqUnit);

  // Единицы совпадают (или пустые) — ничего не меняем
  if (!pu || !ru || pu === ru) return { price, applied: pu === ru };

  // Ищем правило по нормализованным единицам
  const rule = rules.find(
    (r) =>
      r.активно !== false &&
      normUnit(r.единица_в_прайсе) === pu &&
      normUnit(r.единица_в_запросе) === ru
  );
  if (!rule) return { price, applied: false }; // правило не найдено — оставляем

  const op = String(rule.операция ?? '').trim().toLowerCase();
  const isDynamic =
    String(rule.тип_коэффициента).toLowerCase() === 'динамический' ||
    rule.коэффициент === null ||
    rule.коэффициент === undefined;

  // Динамический коэффициент (упак. → шт. или шт. → упак.) — берём perPack
  if (isDynamic) {
    if (!perPack || perPack <= 0) return { price, applied: false };
    if (op.startsWith('раздел')) return { price: price / perPack, applied: true };
    if (op.startsWith('умнож'))  return { price: price * perPack, applied: true };
    return { price, applied: false };
  }

  // Фиксированный коэффициент
  const k = parsePrice(rule.коэффициент);
  if (!k) return { price, applied: false };

  if (op.startsWith('раздел')) return { price: price / k, applied: true };
  if (op.startsWith('умнож'))  return { price: price * k, applied: true };
  return { price, applied: false };
}

/* -------------------------------------------------------------------------
 * 5. ИЗВЛЕЧЕНИЕ ПОЛЕЙ СТРОКИ КП
 * ---------------------------------------------------------------------- */

const name      = curItem.output ?? '';               // "Наименование оборудование"
const qtyRaw    = loopItem['кол_во'];                 // "Кол-во" (для вывода как есть)
const qty       = parseQty(qtyRaw);                   // числовое значение для расчётов
const unitReq   = loopItem['ед_измерения'] ?? '';     // "Ед. изм." — единица запроса/КП
const unitPrice = pos['Ед.измерения.'] ?? '';         // единица в прайсе
const currency  = pos['Валюта'] ?? 'RUB';             // валюта прайса
const vatRaw    = pos['Ставка НДС'];                  // "НДС %" — выводим как есть
const vatRate   = parseVat(vatRaw);                   // числовая ставка НДС
const perPack   = parsePrice(pos['Кол-во в упак.']);  // для динамических коэффициентов

/* -------------------------------------------------------------------------
 * 6. ОПРЕДЕЛЕНИЕ НАЦЕНКИ
 * ---------------------------------------------------------------------- */

/**
 * Приоритет из ТЗ:
 *   1) "Наценка" из позиции (если задано и > 0);
 *   2) иначе — "Процент" из ноды "Получить базовую наценку" (в %).
 *
 * Интерпретация значения "Наценка":
 *   по примеру в ТЗ (232,25 × 1,4 = 325,15) — это множитель (1.4),
 *   но если прилетело большое значение (например 30) — трактуем как %.
 *   Порог разделения — MARKUP_PERCENT_THRESHOLD (5).
 */
const posMarkupVal = parsePrice(pos['Наценка']);

let markupFactor;
if (posMarkupVal > 0) {
  markupFactor =
    posMarkupVal > MARKUP_PERCENT_THRESHOLD
      ? 1 + posMarkupVal / 100   // 30  → 1.30
      : posMarkupVal;            // 1.4 → 1.40
} else {
  // Fallback: процент из базовой наценки (всегда в %, например 30)
  const baseProc = parsePrice($('Получить базовую наценку').first().json['Процент']);
  markupFactor = 1 + baseProc / 100;
}

/* -------------------------------------------------------------------------
 * 7. ФОРМИРОВАНИЕ РЕЗУЛЬТАТА (ЗНАЧЕНИЯ ПО УМОЛЧАНИЮ)
 * ---------------------------------------------------------------------- */

// Базовая цена из прайса: уже с НДС, за 1 единицу в единице прайса
const basePriceRaw = parsePrice(pos['Цена (оптовая)']);

// Заготовка строки. Если цены нет — оставляем значения по умолчанию.
const row = {
  'Наименование оборудование': name,
  'Кол-во':                    qtyRaw,
  'Ед. изм.':                  unitReq,
  'Цена за ед. в руб':         'Цена по запросу',
  'НДС %':                     vatRaw,
  'Итого без НДС':             '—',
  'Сумма НДС':                 '—',
  'Итого с НДС':               '—',
};

/* -------------------------------------------------------------------------
 * 8. РАСЧЁТ (только если цена в прайсе > 0)
 * ---------------------------------------------------------------------- */

if (basePriceRaw > 0) {
  // Шаг 1. Конвертация валюты (EUR/USD/CNY → RUB по курсу ЦБ + 5%)
  let price = toRub(basePriceRaw, currency, rates);

  // Шаг 2. Пересчёт единицы измерения прайса в единицу запроса
  //         (например, 622.20 ₽/кг → 0.6222 ₽/г)
  price = convertUnit(price, unitPrice, unitReq, unitRules, perPack).price;

  // Шаг 3. Наценка (после конвертации валюты и единиц!)
  price = price * markupFactor;

  // Шаг 4. Округление цены за единицу С УЧЁТОМ РАЗМЕРА ЕДИНИЦЫ:
  //   - г, мг, мл, мкл → 4 знака после запятой (0.6222 → 0.8089);
  //   - кг, л, м, шт. и прочие → до целых рублей (325.15 → 325).
  //   Единица запроса берётся из КП (unitReq) — именно её видит пользователь.
  const priceRub = roundUnitPrice(price, unitReq);

  // Шаг 5. Итого с НДС по строке = цена за единицу × кол-во.
  //   Т.к. цена может быть нецелой (для г/мг/мл/мкл),
  //   итог округляем до копеек (2 знака).
  const totalWithVat = round2(priceRub * qty);

  // Шаг 6. Итого без НДС и НДС по строке.
  //   Если НДС > 0:  Итого без НДС = Итого с НДС / (1 + ставка/100)
  //                  НДС          = Итого с НДС − Итого без НДС
  //   Если Без НДС:  Итого без НДС = Итого с НДС, НДС = 0
  //   Суммы НЕ округляем до целых — оставляем копейки.
  let totalNoVat, vatSum;
  if (vatRate > 0) {
    totalNoVat = round2(totalWithVat / (1 + vatRate / 100));
    vatSum     = round2(totalWithVat - totalNoVat);
  } else {
    totalNoVat = totalWithVat;
    vatSum     = 0;
  }

  // Записываем рассчитанные значения в строку
  row['Цена за ед. в руб'] = priceRub;
  row['Итого без НДС']     = totalNoVat;
  row['Сумма НДС']         = vatSum;
  row['Итого с НДС']       = totalWithVat;
}

/* -------------------------------------------------------------------------
 * 9. ВОЗВРАТ РЕЗУЛЬТАТА
 * ---------------------------------------------------------------------- */

return [{ json: row }];

// ============================================================
// 1. ИСТОЧНИКИ ДАННЫХ
// ============================================================
const кпДанные        = $('Сохранить КП').first().json;
const данныеКомпании  = $('Запрос данных по компании').first().json.result[0];
const данныеМенеджера = $('Запрос данных по менеджеру').first().json.result[0];
const позицииСырые    = $('Aggregate').first().json.data;
const входныеДанные   = $input.first().json.result[0];

// ============================================================
// 2. ХЕЛПЕРЫ
// ============================================================
// Преобразование в число (поддержка запятой как разделителя)
const вЧисло = (v) => {
  if (v === undefined || v === null || v === '') return 0;
  if (typeof v === 'number') return v;
  return parseFloat(String(v).replace(/\s/g, '').replace(',', '.')) || 0;
};

// Округление до 2 знаков
const округлить2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;

// Проверка, что поле реально пришло
const есть = (v) => v !== undefined && v !== null && v !== '';

// ============================================================
// 3. РЕКВИЗИТЫ КП
// ============================================================
const сегодня = new Date();
const датаКП = [
  String(сегодня.getDate()).padStart(2, '0'),
  String(сегодня.getMonth() + 1).padStart(2, '0'),
  сегодня.getFullYear()
].join('.');

const компания = (данныеКомпании.TITLE || '').replace(/\//g, '').trim();

const адрес = [
  входныеДанные.POSTAL_CODE,
  входныеДанные.REGION,
  входныеДанные.PROVINCE,
  входныеДанные.ADDRESS_1,
  входныеДанные.ADDRESS_2
].filter((p) => p && String(p).trim()).join(', ');

const фиоМенеджера = `${данныеМенеджера.LAST_NAME || ''} ${данныеМенеджера.NAME || ''}`.trim();

// ============================================================
// 4. НОРМАЛИЗАЦИЯ СПИСКА ПОЗИЦИЙ
// ============================================================
// Aggregate может вернуть массив или объект — приводим к массиву.
const позицииВход = Array.isArray(позицииСырые)
  ? позицииСырые
  : (позицииСырые && typeof позицииСырые === 'object' ? Object.values(позицииСырые) : []);

// ============================================================
// 5. РАСЧЁТ ПОЗИЦИЙ И ИТОГОВ
// ------------------------------------------------------------
// Для каждой позиции:
//   • берём исходные поля по русским названиям (как в Aggregate);
//   • суммы берём из источника, если они там есть
//     ("Итого без НДС", "Сумма НДС", "Итого с НДС"), иначе считаем сами;
//   • номер позиции = индекс + 1.
//
// ЛОГИКА РАСЧЁТА, если источник не дал готовых сумм:
//   Цена в "Цена за ед. в руб" считается С НДС.
//     суммаСНДС    = цена × количество
//     суммаБезНДС  = суммаСНДС / (1 + ставкаНДС / 100)
//     суммаНДС     = суммаСНДС − суммаБезНДС
//   Если ставка НДС = 0 — НДС не начисляется, суммаСНДС = суммаБезНДС.
//
// Группировка по ставкам НДС ведётся, чтобы потом показать
// разбивку: "22%: 145,89, 10%: 0,73".
// ============================================================
const группыНДС = Object.create(null);
let итогоБезНДС = 0;
let итогоНДС    = 0;
let итогоСНДС   = 0;

const позиции = позицииВход.map((элемент, индекс) => {
  // --- исходные поля ---
  const наименование = элемент['Наименование оборудование'] || элемент['Наименование'] || '';
  const единица      = элемент['Ед. изм.'] || '';
  const количество   = вЧисло(элемент['Кол-во']);
  const цена         = вЧисло(элемент['Цена за ед. в руб']);

  let ставкаНДС = вЧисло(элемент['НДС %']);
  if (ставкаНДС > 0 && ставкаНДС < 1) ставкаНДС = ставкаНДС * 100; // 0.22 → 22

  // --- суммы по позиции ---
  let суммаБезНДС, суммаНДС, суммаСНДС;

  if (есть(элемент['Итого без НДС']) && есть(элемент['Сумма НДС']) && есть(элемент['Итого с НДС'])) {
    // Источник уже посчитал — доверяем ему
    суммаБезНДС = округлить2(вЧисло(элемент['Итого без НДС']));
    суммаНДС    = округлить2(вЧисло(элемент['Сумма НДС']));
    суммаСНДС   = округлить2(вЧисло(элемент['Итого с НДС']));
  } else if (ставкаНДС > 0) {
    // Считаем: цена указана С НДС
    суммаСНДС   = округлить2(цена * количество);
    суммаБезНДС = округлить2(суммаСНДС / (1 + ставкаНДС / 100));
    суммаНДС    = округлить2(суммаСНДС - суммаБезНДС);
  } else {
    // НДС не начисляется
    суммаБезНДС = округлить2(цена * количество);
    суммаНДС    = 0;
    суммаСНДС   = суммаБезНДС;
  }

  // --- накопление по ставке НДС ---
  const ключ = String(ставкаНДС);
  if (!группыНДС[ключ]) {
    группыНДС[ключ] = { ставка: ставкаНДС, безНДС: 0, ндс: 0, сНДС: 0 };
  }
  группыНДС[ключ].безНДС += суммаБезНДС;
  группыНДС[ключ].ндс    += суммаНДС;
  группыНДС[ключ].сНДС   += суммаСНДС;

  // --- общие итоги ---
  итогоБезНДС += суммаБезНДС;
  итогоНДС    += суммаНДС;
  итогоСНДС   += суммаСНДС;

  // --- чистая позиция ---
  return {
    номер:       индекс + 1,   // порядковый номер с 1
    наименование,
    единица,
    количество,
    цена,
    ставкаНДС,
    суммаБезНДС,
    суммаНДС,
    суммаСНДС
  };
});

// Финальное округление общих сумм
итогоБезНДС = округлить2(итогоБезНДС);
итогоНДС    = округлить2(итогоНДС);
итогоСНДС   = округлить2(итогоСНДС);

// Разбивка по ставкам (от большей к меньшей, без нулевой)
const разбивкаНДС = Object.values(группыНДС)
  .filter((g) => g.ставка > 0)
  .sort((a, b) => b.ставка - a.ставка)
  .map((g) => ({
    ставка:    g.ставка,
    безНДС:    округлить2(g.безНДС),
    ндс:       округлить2(g.ндс),
    сНДС:      округлить2(g.сНДС)
  }));

// ============================================================
// 6. ИТОГОВЫЙ JSON
// ============================================================
return [{
  json: {
    номерКП: кпДанные['ID КП'] || '',
    датаКП,
    компания,
    инн: данныеКомпании.UF_CRM_1790067226701 || '',
    адрес,

    позиции,

    итоги: {
      безНДС:      итогоБезНДС,
      ндс:         итогоНДС,
      сНДС:        итогоСНДС,
      разбивкаНДС
    },

    менеджер: {
      фио:       фиоМенеджера,
      должность: данныеМенеджера.WORK_POSITION || '',
      телефон:   `+7 (812) 607-11-18, доб. ${данныеМенеджера.UF_PHONE_INNER || ''}`,
      мобильный: данныеМенеджера.UF_USR_1790059625304 || '',
      почта:     данныеМенеджера.UF_USR_1790059556885 || ''
    }
  }
}];

const html = $json.html;
const body = JSON.stringify({ html, filename: "KP_INVITRO" });
return [{ json: { body } }];
